CREATE TYPE "HandoverState" AS ENUM ('SCHEDULED','CANCELLED');
CREATE TYPE "HandoverOutcome" AS ENUM ('COMPLETED','DELAYED','MISSED');
CREATE TABLE "Handover"("id" TEXT PRIMARY KEY,"familyId" TEXT NOT NULL,"createdById" TEXT NOT NULL,"currentVersionId" TEXT UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("familyId") REFERENCES "Family"("id") ON DELETE RESTRICT,FOREIGN KEY("createdById") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE "HandoverVersion"("id" TEXT PRIMARY KEY,"handoverId" TEXT NOT NULL,"revision" INTEGER NOT NULL,"state" "HandoverState" NOT NULL DEFAULT 'SCHEDULED',"scheduledAt" TIMESTAMPTZ(3) NOT NULL,"timeZone" TEXT NOT NULL,"location" TEXT NOT NULL,"notes" TEXT,"fromParentId" TEXT NOT NULL,"toParentId" TEXT NOT NULL,"changedById" TEXT NOT NULL,"changeReason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("handoverId","revision"),FOREIGN KEY("handoverId") REFERENCES "Handover"("id") ON DELETE RESTRICT,FOREIGN KEY("fromParentId") REFERENCES "User"("id") ON DELETE RESTRICT,FOREIGN KEY("toParentId") REFERENCES "User"("id") ON DELETE RESTRICT,FOREIGN KEY("changedById") REFERENCES "User"("id") ON DELETE RESTRICT,CHECK("fromParentId"<>"toParentId"),CHECK(char_length("location") BETWEEN 1 AND 500),CHECK("notes" IS NULL OR char_length("notes") BETWEEN 1 AND 5000),CHECK("changeReason" IS NULL OR char_length("changeReason") BETWEEN 1 AND 500));
ALTER TABLE "Handover" ADD CONSTRAINT "Handover_currentVersionId_fkey" FOREIGN KEY("currentVersionId") REFERENCES "HandoverVersion"("id") ON DELETE RESTRICT;
CREATE TABLE "HandoverVersionChild"("versionId" TEXT NOT NULL,"childId" TEXT NOT NULL,PRIMARY KEY("versionId","childId"),FOREIGN KEY("versionId") REFERENCES "HandoverVersion"("id") ON DELETE RESTRICT,FOREIGN KEY("childId") REFERENCES "Child"("id") ON DELETE RESTRICT);
CREATE TABLE "HandoverChecklistItem"("id" TEXT PRIMARY KEY,"versionId" TEXT NOT NULL,"label" TEXT NOT NULL,"position" INTEGER NOT NULL,UNIQUE("versionId","position"),FOREIGN KEY("versionId") REFERENCES "HandoverVersion"("id") ON DELETE RESTRICT,CHECK(char_length("label") BETWEEN 1 AND 160),CHECK("position">=0));
CREATE TABLE "HandoverAcknowledgement"("id" TEXT PRIMARY KEY,"handoverId" TEXT NOT NULL,"versionId" TEXT NOT NULL,"userId" TEXT NOT NULL,"outcome" "HandoverOutcome" NOT NULL,"note" TEXT,"acknowledgedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("versionId","userId"),FOREIGN KEY("handoverId") REFERENCES "Handover"("id") ON DELETE RESTRICT,FOREIGN KEY("versionId") REFERENCES "HandoverVersion"("id") ON DELETE RESTRICT,FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE RESTRICT,CHECK("note" IS NULL OR char_length("note") BETWEEN 1 AND 2000));
CREATE TABLE "HandoverAcknowledgementItem"("acknowledgementId" TEXT NOT NULL,"checklistItemId" TEXT NOT NULL,PRIMARY KEY("acknowledgementId","checklistItemId"),FOREIGN KEY("acknowledgementId") REFERENCES "HandoverAcknowledgement"("id") ON DELETE RESTRICT,FOREIGN KEY("checklistItemId") REFERENCES "HandoverChecklistItem"("id") ON DELETE RESTRICT);
CREATE INDEX "Handover_familyId_createdAt_idx" ON "Handover"("familyId","createdAt"); CREATE INDEX "HandoverVersion_scheduledAt_idx" ON "HandoverVersion"("scheduledAt"); CREATE INDEX "HandoverVersionChild_childId_idx" ON "HandoverVersionChild"("childId"); CREATE INDEX "HandoverAcknowledgement_userId_acknowledgedAt_idx" ON "HandoverAcknowledgement"("userId","acknowledgedAt");
ALTER TABLE "Handover" ENABLE ROW LEVEL SECURITY; ALTER TABLE "HandoverVersion" ENABLE ROW LEVEL SECURITY; ALTER TABLE "HandoverVersionChild" ENABLE ROW LEVEL SECURITY; ALTER TABLE "HandoverChecklistItem" ENABLE ROW LEVEL SECURITY; ALTER TABLE "HandoverAcknowledgement" ENABLE ROW LEVEL SECURITY; ALTER TABLE "HandoverAcknowledgementItem" ENABLE ROW LEVEL SECURITY;
CREATE POLICY handover_select ON "Handover" FOR SELECT TO coparent_runtime USING(is_coparent_family_member("familyId"));
CREATE POLICY handover_version_select ON "HandoverVersion" FOR SELECT TO coparent_runtime USING(EXISTS(SELECT 1 FROM "Handover" h WHERE h."id"="handoverId" AND is_coparent_family_member(h."familyId")));
CREATE POLICY handover_child_select ON "HandoverVersionChild" FOR SELECT TO coparent_runtime USING(EXISTS(SELECT 1 FROM "HandoverVersion" v JOIN "Handover" h ON h."id"=v."handoverId" WHERE v."id"="versionId" AND is_coparent_family_member(h."familyId")));
CREATE POLICY handover_checklist_select ON "HandoverChecklistItem" FOR SELECT TO coparent_runtime USING(EXISTS(SELECT 1 FROM "HandoverVersion" v JOIN "Handover" h ON h."id"=v."handoverId" WHERE v."id"="versionId" AND is_coparent_family_member(h."familyId")));
CREATE POLICY handover_ack_select ON "HandoverAcknowledgement" FOR SELECT TO coparent_runtime USING(EXISTS(SELECT 1 FROM "Handover" h WHERE h."id"="handoverId" AND is_coparent_family_member(h."familyId")));
CREATE POLICY handover_ack_item_select ON "HandoverAcknowledgementItem" FOR SELECT TO coparent_runtime USING(EXISTS(SELECT 1 FROM "HandoverAcknowledgement" a JOIN "Handover" h ON h."id"=a."handoverId" WHERE a."id"="acknowledgementId" AND is_coparent_family_member(h."familyId")));
CREATE FUNCTION protect_handover() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Handover records are permanent'; END IF; IF NEW."id" IS DISTINCT FROM OLD."id" OR NEW."familyId" IS DISTINCT FROM OLD."familyId" OR NEW."createdById" IS DISTINCT FROM OLD."createdById" OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt" THEN RAISE EXCEPTION 'Handover identity is immutable'; END IF; IF NEW."currentVersionId" IS DISTINCT FROM OLD."currentVersionId" AND nullif(current_setting('app.handover_transition_id',TRUE),'') IS DISTINCT FROM OLD."id" THEN RAISE EXCEPTION 'Handover versions may change only through a transition function'; END IF; RETURN NEW; END; $$;
CREATE FUNCTION prevent_handover_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Handover history is immutable'; END; $$;
CREATE TRIGGER handover_protected BEFORE UPDATE OR DELETE ON "Handover" FOR EACH ROW EXECUTE FUNCTION protect_handover(); CREATE TRIGGER handover_version_immutable BEFORE UPDATE OR DELETE ON "HandoverVersion" FOR EACH ROW EXECUTE FUNCTION prevent_handover_history_mutation(); CREATE TRIGGER handover_child_immutable BEFORE UPDATE OR DELETE ON "HandoverVersionChild" FOR EACH ROW EXECUTE FUNCTION prevent_handover_history_mutation(); CREATE TRIGGER handover_checklist_immutable BEFORE UPDATE OR DELETE ON "HandoverChecklistItem" FOR EACH ROW EXECUTE FUNCTION prevent_handover_history_mutation(); CREATE TRIGGER handover_ack_immutable BEFORE UPDATE OR DELETE ON "HandoverAcknowledgement" FOR EACH ROW EXECUTE FUNCTION prevent_handover_history_mutation(); CREATE TRIGGER handover_ack_item_immutable BEFORE UPDATE OR DELETE ON "HandoverAcknowledgementItem" FOR EACH ROW EXECUTE FUNCTION prevent_handover_history_mutation();
CREATE FUNCTION insert_coparent_handover_version(target_version TEXT,target_handover TEXT,target_revision INTEGER,target_state TEXT,target_scheduled TIMESTAMPTZ,target_timezone TEXT,target_location TEXT,target_notes TEXT,target_from TEXT,target_to TEXT,target_actor TEXT,target_reason TEXT,target_children TEXT[],target_item_ids TEXT[],target_item_labels TEXT[]) RETURNS BOOLEAN LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ BEGIN IF target_from=target_to OR char_length(btrim(target_location)) NOT BETWEEN 1 AND 500 OR coalesce(array_length(target_children,1),0)<1 OR array_length(target_item_ids,1) IS DISTINCT FROM array_length(target_item_labels,1) OR EXISTS(SELECT 1 FROM unnest(target_item_labels) label WHERE char_length(btrim(label)) NOT BETWEEN 1 AND 160) THEN RETURN FALSE; END IF; INSERT INTO public."HandoverVersion"("id","handoverId","revision","state","scheduledAt","timeZone","location","notes","fromParentId","toParentId","changedById","changeReason","createdAt") VALUES(target_version,target_handover,target_revision,target_state::public."HandoverState",target_scheduled,target_timezone,btrim(target_location),nullif(btrim(target_notes),''),target_from,target_to,target_actor,nullif(btrim(target_reason),''),timezone('UTC',clock_timestamp())); INSERT INTO public."HandoverVersionChild" SELECT target_version,c FROM unnest(target_children)c; INSERT INTO public."HandoverChecklistItem" SELECT i,target_version,btrim(l),ord-1 FROM unnest(target_item_ids,target_item_labels) WITH ORDINALITY t(i,l,ord); RETURN TRUE; EXCEPTION WHEN invalid_text_representation OR unique_violation OR foreign_key_violation OR check_violation THEN RETURN FALSE; END; $$;
CREATE FUNCTION create_coparent_handover(target_id TEXT,target_version TEXT,target_family TEXT,target_scheduled TIMESTAMPTZ,target_timezone TEXT,target_location TEXT,target_notes TEXT,target_from TEXT,target_to TEXT,target_children TEXT[],target_item_ids TEXT[],target_item_labels TEXT[]) RETURNS TEXT LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE actor TEXT:=public.current_coparent_user_id(); ok BOOLEAN; BEGIN IF actor IS NULL OR NOT public.is_coparent_family_member(target_family,TRUE) OR EXISTS(SELECT 1 FROM unnest(ARRAY[target_from,target_to])u WHERE NOT EXISTS(SELECT 1 FROM public."FamilyMembership" WHERE "familyId"=target_family AND "userId"=u AND "role" IN('OWNER','PARENT'))) OR EXISTS(SELECT 1 FROM unnest(target_children)c WHERE NOT EXISTS(SELECT 1 FROM public."Child" WHERE "id"=c AND "familyId"=target_family)) THEN RETURN NULL; END IF; INSERT INTO public."Handover"("id","familyId","createdById","createdAt") VALUES(target_id,target_family,actor,timezone('UTC',clock_timestamp())); SELECT public.insert_coparent_handover_version(target_version,target_id,1,'SCHEDULED',target_scheduled,target_timezone,target_location,target_notes,target_from,target_to,actor,NULL,target_children,target_item_ids,target_item_labels) INTO ok; IF NOT ok THEN RAISE EXCEPTION 'Invalid handover'; END IF; PERFORM set_config('app.handover_transition_id',target_id,TRUE); UPDATE public."Handover" SET "currentVersionId"=target_version WHERE "id"=target_id; PERFORM set_config('app.handover_transition_id','',TRUE); INSERT INTO public."AuditEvent"("id","familyId","actorId","action","entityType","entityId","occurredAt") VALUES(gen_random_uuid()::TEXT,target_family,actor,'HANDOVER_CREATED','Handover',target_id,timezone('UTC',clock_timestamp())); RETURN target_id; END; $$;
CREATE FUNCTION revise_coparent_handover(target_id TEXT,target_version TEXT,target_family TEXT,target_scheduled TIMESTAMPTZ,target_timezone TEXT,target_location TEXT,target_notes TEXT,target_from TEXT,target_to TEXT,target_reason TEXT,target_children TEXT[],target_item_ids TEXT[],target_item_labels TEXT[]) RETURNS TEXT LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE actor TEXT:=public.current_coparent_user_id(); rev INTEGER; ok BOOLEAN; BEGIN SELECT v."revision" INTO rev FROM public."Handover" h JOIN public."HandoverVersion" v ON v."id"=h."currentVersionId" WHERE h."id"=target_id AND h."familyId"=target_family AND v."state"='SCHEDULED' FOR UPDATE OF h; IF rev IS NULL OR NOT public.is_coparent_family_member(target_family,TRUE) OR char_length(btrim(target_reason)) NOT BETWEEN 1 AND 500 OR EXISTS(SELECT 1 FROM unnest(ARRAY[target_from,target_to])u WHERE NOT EXISTS(SELECT 1 FROM public."FamilyMembership" WHERE "familyId"=target_family AND "userId"=u AND "role" IN('OWNER','PARENT'))) OR EXISTS(SELECT 1 FROM unnest(target_children)c WHERE NOT EXISTS(SELECT 1 FROM public."Child" WHERE "id"=c AND "familyId"=target_family)) THEN RETURN NULL; END IF; SELECT public.insert_coparent_handover_version(target_version,target_id,rev+1,'SCHEDULED',target_scheduled,target_timezone,target_location,target_notes,target_from,target_to,actor,target_reason,target_children,target_item_ids,target_item_labels) INTO ok; IF NOT ok THEN RAISE EXCEPTION 'Invalid handover'; END IF; PERFORM set_config('app.handover_transition_id',target_id,TRUE); UPDATE public."Handover" SET "currentVersionId"=target_version WHERE "id"=target_id; PERFORM set_config('app.handover_transition_id','',TRUE); INSERT INTO public."AuditEvent"("id","familyId","actorId","action","entityType","entityId","occurredAt") VALUES(gen_random_uuid()::TEXT,target_family,actor,'HANDOVER_REVISED','Handover',target_id,timezone('UTC',clock_timestamp())); RETURN target_id; END; $$;
CREATE FUNCTION cancel_coparent_handover(target_id TEXT,target_version TEXT,target_family TEXT,target_reason TEXT) RETURNS TEXT LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE actor TEXT:=public.current_coparent_user_id(); v public."HandoverVersion"%ROWTYPE; ok BOOLEAN; item_ids TEXT[]; item_labels TEXT[]; child_ids TEXT[]; BEGIN SELECT hv.* INTO v FROM public."Handover" h JOIN public."HandoverVersion" hv ON hv."id"=h."currentVersionId" WHERE h."id"=target_id AND h."familyId"=target_family AND hv."state"='SCHEDULED' FOR UPDATE OF h; IF v."id" IS NULL OR NOT public.is_coparent_family_member(target_family,TRUE) OR char_length(btrim(target_reason)) NOT BETWEEN 1 AND 500 THEN RETURN NULL; END IF; SELECT array_agg("childId") INTO child_ids FROM public."HandoverVersionChild" WHERE "versionId"=v."id"; SELECT array_agg(gen_random_uuid()::TEXT ORDER BY "position"),array_agg("label" ORDER BY "position") INTO item_ids,item_labels FROM public."HandoverChecklistItem" WHERE "versionId"=v."id"; SELECT public.insert_coparent_handover_version(target_version,target_id,v."revision"+1,'CANCELLED',v."scheduledAt",v."timeZone",v."location",v."notes",v."fromParentId",v."toParentId",actor,target_reason,child_ids,coalesce(item_ids,ARRAY[]::TEXT[]),coalesce(item_labels,ARRAY[]::TEXT[])) INTO ok; IF NOT ok THEN RAISE EXCEPTION 'Invalid cancellation'; END IF; PERFORM set_config('app.handover_transition_id',target_id,TRUE); UPDATE public."Handover" SET "currentVersionId"=target_version WHERE "id"=target_id; PERFORM set_config('app.handover_transition_id','',TRUE); INSERT INTO public."AuditEvent"("id","familyId","actorId","action","entityType","entityId","occurredAt") VALUES(gen_random_uuid()::TEXT,target_family,actor,'HANDOVER_CANCELLED','Handover',target_id,timezone('UTC',clock_timestamp())); RETURN target_id; END; $$;
CREATE FUNCTION acknowledge_coparent_handover(target_id TEXT,target_ack TEXT,target_family TEXT,target_outcome TEXT,target_note TEXT,target_checked TEXT[]) RETURNS TEXT LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog SET timezone='UTC' AS $$ DECLARE actor TEXT:=public.current_coparent_user_id(); version_id TEXT; BEGIN SELECT h."currentVersionId" INTO version_id FROM public."Handover" h JOIN public."HandoverVersion" v ON v."id"=h."currentVersionId" WHERE h."id"=target_id AND h."familyId"=target_family AND v."state"='SCHEDULED' AND actor IN(v."fromParentId",v."toParentId") FOR UPDATE OF h; IF version_id IS NULL OR target_outcome NOT IN('COMPLETED','DELAYED','MISSED') OR target_outcome IN('DELAYED','MISSED') AND coalesce(char_length(btrim(target_note)),0)<1 OR EXISTS(SELECT 1 FROM unnest(target_checked)i WHERE NOT EXISTS(SELECT 1 FROM public."HandoverChecklistItem" WHERE "id"=i AND "versionId"=version_id)) THEN RETURN NULL; END IF; INSERT INTO public."HandoverAcknowledgement" VALUES(target_ack,target_id,version_id,actor,target_outcome::public."HandoverOutcome",nullif(btrim(target_note),''),timezone('UTC',clock_timestamp())); INSERT INTO public."HandoverAcknowledgementItem" SELECT target_ack,i FROM unnest(target_checked)i; INSERT INTO public."AuditEvent"("id","familyId","actorId","action","entityType","entityId","occurredAt","metadata") VALUES(gen_random_uuid()::TEXT,target_family,actor,'HANDOVER_'||target_outcome,'Handover',target_id,timezone('UTC',clock_timestamp()),jsonb_build_object('versionId',version_id)); RETURN target_id; EXCEPTION WHEN unique_violation OR invalid_text_representation THEN RETURN NULL; END; $$;
REVOKE ALL ON FUNCTION insert_coparent_handover_version(TEXT,TEXT,INTEGER,TEXT,TIMESTAMPTZ,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT[],TEXT[],TEXT[]) FROM PUBLIC; REVOKE ALL ON FUNCTION create_coparent_handover(TEXT,TEXT,TEXT,TIMESTAMPTZ,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT[],TEXT[],TEXT[]) FROM PUBLIC; REVOKE ALL ON FUNCTION revise_coparent_handover(TEXT,TEXT,TEXT,TIMESTAMPTZ,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT[],TEXT[],TEXT[]) FROM PUBLIC; REVOKE ALL ON FUNCTION cancel_coparent_handover(TEXT,TEXT,TEXT,TEXT) FROM PUBLIC; REVOKE ALL ON FUNCTION acknowledge_coparent_handover(TEXT,TEXT,TEXT,TEXT,TEXT,TEXT[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION create_coparent_handover(TEXT,TEXT,TEXT,TIMESTAMPTZ,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT[],TEXT[],TEXT[]) TO coparent_runtime; GRANT EXECUTE ON FUNCTION revise_coparent_handover(TEXT,TEXT,TEXT,TIMESTAMPTZ,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT,TEXT[],TEXT[],TEXT[]) TO coparent_runtime; GRANT EXECUTE ON FUNCTION cancel_coparent_handover(TEXT,TEXT,TEXT,TEXT) TO coparent_runtime; GRANT EXECUTE ON FUNCTION acknowledge_coparent_handover(TEXT,TEXT,TEXT,TEXT,TEXT,TEXT[]) TO coparent_runtime;
GRANT SELECT ON "Handover","HandoverVersion","HandoverVersionChild","HandoverChecklistItem","HandoverAcknowledgement","HandoverAcknowledgementItem" TO coparent_runtime;
